import ast

def extract_energy(payload):
    if pd.isna(payload) or payload == "":
        return 0.0
    try:
        payload_dict = json.loads(payload.replace("'", '"'))
        # Try finding energy in metrics
        metrics = payload_dict.get('metrics', {})
        if 'energy_kwh' in metrics:
            return float(metrics['energy_kwh'])
        elif 'energy_wh' in metrics:
            return float(metrics['energy_wh']) / 1000.0

        # Try finding energy in data -> readings
        data = payload_dict.get('data', {})
        readings = data.get('readings', [])
        for r in readings:
            if r.get('k') == 'energy':
                if r.get('u') == 'Wh':
                    return float(r.get('v', 0)) / 1000.0
                elif r.get('u') == 'kWh':
                    return float(r.get('v', 0))
        return 0.0
    except:
        return 0.0

